#!/usr/bin/env python3
"""
Write common/psa/_selected.py so a PyInstaller build bundles exactly one
PSA provider. Run once per CI build job, before `pyinstaller`:

    python scripts/select_provider.py rivet

Add new providers to PROVIDERS as they're implemented (see the plan's
phased rollout: syncro/atera in Phase 1, ninjaone/halopsa in Phase 2).
"""

import sys
from pathlib import Path

PROVIDERS = {
    "rivet": ("rivet_select", "make_provider"),
}

TEMPLATE = """\
# Generated by scripts/select_provider.py - do not edit, not committed.
from .{module} import {cls} as PROVIDER_CLASS

PROVIDER_NAME = "{name}"
"""


def main():
    if len(sys.argv) != 2 or sys.argv[1] not in PROVIDERS:
        names = ", ".join(sorted(PROVIDERS))
        print(f"usage: select_provider.py <provider>\navailable providers: {names}", file=sys.stderr)
        sys.exit(1)

    name = sys.argv[1]
    module, cls = PROVIDERS[name]
    out_path = Path(__file__).resolve().parent.parent / "common" / "psa" / "_selected.py"
    out_path.write_text(TEMPLATE.format(module=module, cls=cls, name=name))
    print(f"wrote {out_path} -> provider={name}")


if __name__ == "__main__":
    main()
